const viewer = (window.viewer = new Cesium.Viewer('cesiumContainer', {
  baseLayer: new Cesium.ImageryLayer(new Cesium.OpenStreetMapImageryProvider({
    url: 'https://tile.openstreetmap.org/',
    maximumLevel: 18,
  })),
  baseLayerPicker: false,
  navigationHelpButton: false,
  animation: false,
  timeline: false,
  geocoder: false,
  homeButton: false,
  sceneModePicker: false,
  fullscreenButton: false,
  infoBox: false,
  selectionIndicator: false,
}));

viewer.scene.globe.enableLighting = false;

// Add visible markers for both landmarks
viewer.entities.add({
  name: 'Statue of Liberty',
  position: Cesium.Cartesian3.fromDegrees(-74.0445, 40.6892, 0.0),
  billboard: {
    image: 'https://maps.google.com/mapfiles/ms/icons/green-dot.png',
    verticalOrigin: Cesium.VerticalOrigin.BOTTOM,
    scale: 1.2,
  },
  label: {
    text: 'Statue of Liberty',
    font: '14px sans-serif',
    fillColor: Cesium.Color.WHITE,
    outlineColor: Cesium.Color.BLACK,
    outlineWidth: 2,
    style: Cesium.LabelStyle.FILL_AND_OUTLINE,
    pixelOffset: new Cesium.Cartesian2(0, -40),
    verticalOrigin: Cesium.VerticalOrigin.BOTTOM,
  },
});

viewer.entities.add({
  name: 'Empire State Building',
  position: Cesium.Cartesian3.fromDegrees(-73.9857, 40.7484, 0.0),
  billboard: {
    image: 'https://maps.google.com/mapfiles/ms/icons/red-dot.png',
    verticalOrigin: Cesium.VerticalOrigin.BOTTOM,
    scale: 1.2,
  },
  label: {
    text: 'Empire State Building',
    font: '14px sans-serif',
    fillColor: Cesium.Color.WHITE,
    outlineColor: Cesium.Color.BLACK,
    outlineWidth: 2,
    style: Cesium.LabelStyle.FILL_AND_OUTLINE,
    pixelOffset: new Cesium.Cartesian2(0, -40),
    verticalOrigin: Cesium.VerticalOrigin.BOTTOM,
  },
});

// Start from a NYC overview so the tour has a clear departure point
viewer.camera.setView({
  destination: Cesium.Cartesian3.fromDegrees(-74.006, 40.71, 18000.0),
  orientation: {
    heading: Cesium.Math.toRadians(0.0),
    pitch: Cesium.Math.toRadians(-60.0),
    roll: 0.0,
  },
});

// Stop 1: Fly to Statue of Liberty — 800 m, -35 deg pitch, 3 s
viewer.camera.flyTo({
  destination: Cesium.Cartesian3.fromDegrees(-74.0445, 40.6892, 800.0),
  orientation: {
    heading: Cesium.Math.toRadians(0.0),
    pitch: Cesium.Math.toRadians(-35.0),
    roll: 0.0,
  },
  duration: 3,
  complete: function () {
    // Stop 2: Fly to Empire State Building — 600 m, -30 deg pitch, 2 s, linear easing
    viewer.camera.flyTo({
      destination: Cesium.Cartesian3.fromDegrees(-73.9857, 40.7484, 600.0),
      orientation: {
        heading: Cesium.Math.toRadians(0.0),
        pitch: Cesium.Math.toRadians(-30.0),
        roll: 0.0,
      },
      duration: 2,
      easingFunction: Cesium.EasingFunction.LINEAR_NONE,
    });
  },
});
